def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]

    # Draw each marker's line motif.
    for r, c, color in points:
        if color == 1:
            if c + 1 < w:
                out[r][c + 1] = 5
            if c + 2 < w:
                out[r][c + 2] = 5
                if r - 1 >= 0:
                    out[r - 1][c + 2] = 1

        elif color == 2:
            end = c - 4
            if end >= 0:
                out[r][end] = 2
                for x in range(end + 1, c):
                    out[r][x] = 5

        elif color == 3:
            end = min(h - 1, r + 3)
            for y in range(r + 1, end):
                out[y][c] = 5
            if end > r:
                out[end][c] = 3

        elif color == 6:
            end = max(0, r - 6)
            for y in range(end + 1, r):
                out[y][c] = 5
            if end < r:
                out[end][c] = 6

    # A vertical motif crossing a horizontal 2 motif is highlighted,
    # followed by a diagonal trail down and left.
    for r, c, color in points:
        if color not in (3, 6):
            continue
        for hr, hc, hcolor in points:
            if hcolor != 2:
                continue
            left = hc - 4
            if hr == r or not (left <= c <= hc):
                continue
            lo, hi = sorted((r, hr))
            if lo <= hr <= hi:
                out[hr][c] = 4
                y, x = hr + 1, c - 1
                while y < h and x >= 0:
                    out[y][x] = 4
                    y += 1
                    x -= 1

    return out
